\section*{Question 6}
\begin{itemize}
\item[(a)] \(f(0)=3\) and \(f^{\prime}(0)=-2\)
The third-degree Taylor polynomial for \(f\) about \(x=0\) is
\[
3-2 x+\frac{3}{2!} x^{2}+\frac{-\frac{23}{2}}{3!} x^{3}=3-2 x+\frac{3}{2} x^{2}-\frac{23}{12} x^{3} .
\]
\item[(b)] The first three nonzero terms of the Maclaurin series for \(e^{x}\) are \(1+x+\frac{1}{2!} x^{2}\).
The second-degree Taylor polynomial for \(e^{x} f(x)\) about \(x=0\) is
\[
\begin{aligned}
& 3\left(1+x+\frac{1}{2!} x^{2}\right)-2 x(1+x)+\frac{3}{2} x^{2}(1) \\
& \quad=3+(3-2) x+\left(\frac{3}{2}-2+\frac{3}{2}\right) x^{2} \\
& \quad=3+x+x^{2}
\end{aligned}
\]
\item[(c)] \(h(1)=\int_{0}^{1} f(t) d t\)
\[
\begin{aligned}
& \approx \int_{0}^{1}\left(3-2 t+\frac{3}{2} t^{2}-\frac{23}{12} t^{3}\right) d t \\
& =\left[3 t-t^{2}+\frac{1}{2} t^{3}-\frac{23}{48} t^{4}\right]_{t=0}^{t=1} \\
& =3-1+\frac{1}{2}-\frac{23}{48}=\frac{97}{48}
\end{aligned}
\]
\item[(d)] The alternating series error bound is the absolute value of the first omitted term of the series for \(h(1)\).
\[
\begin{aligned}
& \int_{0}^{1}\left(\frac{54}{4!} t^{4}\right) d t=\left[\frac{9}{20} t^{5}\right]_{t=0}^{t=1}=\frac{9}{20} \\
& \text { Error } \leq\left|\frac{9}{20}\right|=0.45
\end{aligned}
\]
